listViewContent.sentence:
SELECT pcategory_group.id as id, pcategory_group.name as familia,
       @ini:=inventarioGrupoCategoriaFecha(?, pcategory_group.id ) as inicial,
       @com:=facturasGrupoCategoriaFecha(?, ?, pcategory_group.id, 0 ) as compras,
       @ven:=facturasGrupoCategoriaFecha(?, ?, pcategory_group.id, 1 ) as ventas,
       @fin:=inventarioGrupoCategoriaFecha(?, pcategory_group.id) as final,
       @ben:=(@ven + @fin - @ini - @com) AS beneficio,
       ((@ben / @com) * 100) AS sobre_compras,
       ((@ben / @ven) * 100) AS sobre_ventas

  FROM pcategory_group;
